<script setup>
import {ref,computed,onMounted,onUnmounted,watch} from 'vue'
import {sources,statuses,dateTime,unwrap,errorText,lines,draft,orderedIds} from './utils'
const props=defineProps({api:{type:Object,default:()=>({})},pluginId:{type:String,default:'AutoSubscribe'}})
const emit=defineEmits(['action'])
const state=ref({config:{enabled:false,tasks:[]},records:[],runs:[],runtime:{},plans:{},next_runs:{},ranks:{}})
const failedPosters=ref(new Set())
const selected=ref(''),tab=ref('history'),sourceFilter=ref(''),statusFilter=ref(''),kindFilter=ref(''),search=ref('')
const loading=ref(false),saving=ref(false),error=ref(''),info=ref(''),editor=ref(false),editing=ref(draft()),textActors=ref(''),textTitles=ref(''),textUrls=ref(''),dragged=ref(''),page=ref(1)
const settingsOpen=ref(false),settingsDraft=ref({}),deleteOpen=ref(false),migrationBusy=ref(false)
const base=computed(()=>`plugin/${props.pluginId}`),tasks=computed(()=>state.value.config.tasks)
const task=computed(()=>tasks.value.find(t=>t.id===selected.value))
const visibleTasks=computed(()=>tasks.value.filter(t=>!sourceFilter.value||t.source===sourceFilter.value))
const runtime=computed(()=>state.value.runtime[selected.value]||{})
const busy=computed(()=>['queued','running'].includes(runtime.value.status))
const rows=computed(()=>state.value.records.filter(r=>(!selected.value||r.task_id===selected.value)&&(!sourceFilter.value||r.source===sourceFilter.value)&&(tab.value!=='pending'||!statusFilter.value||r.status===statusFilter.value)&&(!kindFilter.value||r.media_type===kindFilter.value)&&(!search.value||String(r.title||'').includes(search.value))))
const history=computed(()=>rows.value.filter(r=>['subscribed','migrated'].includes(r.status)))
const completed=computed(()=>rows.value.filter(r=>r.status==='completed'))
const pending=computed(()=>rows.value.filter(r=>!['subscribed','migrated','completed'].includes(r.status)))
const displayed=computed(()=>tab.value==='history'?history.value:tab.value==='completed'?completed.value:tab.value==='pending'?pending.value:(state.value.plans[selected.value]?.items||[]))
const paged=computed(()=>displayed.value.slice((page.value-1)*24,page.value*24))
const runs=computed(()=>state.value.runs.filter(r=>!selected.value||r.task_id===selected.value).slice().reverse())
const sourceOptions=Object.entries(sources).map(([value,title])=>({value,title}))
const kindOptions=[{title:'全部',value:'all'},{title:'电影',value:'movie'},{title:'电视剧',value:'tv'},{title:'动漫剧集',value:'anime'}]
const count=(id)=>state.value.records.filter(r=>r.task_id===id&&['subscribed','migrated','completed'].includes(r.status)).length
let timer
watch([selected,tab,sourceFilter,statusFilter,kindFilter,search],()=>page.value=1)
watch(sourceFilter,()=>{if(task.value && sourceFilter.value && task.value.source!==sourceFilter.value)selected.value=''})
watch(()=>editing.value.source,(value)=>{if(!editing.value.id&&value==='wish')Object.assign(editing.value,{media_type:'all',min_year:0,min_rating:0,min_votes:0,min_popularity:0,cron:'0,30 * * * *',scan_limit:50,max_add:5})})
const taskRuntime=id=>state.value.runtime[id]||[...state.value.runs].reverse().find(r=>r.task_id===id)||{}
async function refresh(silent=false){if(loading.value)return;loading.value=true;try{state.value=unwrap(await props.api.get(`${base.value}/status`));if(!silent)error.value=''}catch(e){error.value=errorText(e)}finally{loading.value=false}}
async function post(path,payload={}){saving.value=true;error.value='';try{const r=unwrap(await props.api.post(base.value+path,payload));emit('action');await refresh(true);return r}catch(e){error.value=errorText(e);throw e}finally{saving.value=false}}
function openEditor(t={}){editing.value=draft(t);textActors.value=editing.value.actors.join('\n');textTitles.value=editing.value.titles.join('\n');textUrls.value=editing.value.rss_urls.join('\n');editor.value=true}
async function save(){const t={...editing.value,actors:lines(textActors.value),titles:lines(textTitles.value),rss_urls:textUrls.value.split('\n').map(x=>x.trim()).filter(Boolean)};if(!t.id)delete t.id;try{const r=await post('/tasks',t);selected.value=r.id;editor.value=false;info.value='任务已保存，原有顺序保持不变'}catch{}}
async function sortTo(from,to){if(saving.value||!from||from===to)return;try{await post('/tasks/order',{ids:orderedIds(tasks.value,from,to)});info.value='任务顺序已保存'}catch{}}
async function move(id,delta){const i=tasks.value.findIndex(t=>t.id===id),other=tasks.value[i+delta];if(other)await sortTo(id,other.id)}
async function run(preview){try{await post(`/tasks/${selected.value}/${preview?'preview':'run'}`);tab.value=preview?'preview':'runs';info.value=preview?'预览已排队，不会创建订阅':'扫描已排队'}catch{}}
async function remove(){try{unwrap(await props.api.delete(`${base.value}/tasks/${selected.value}`));deleteOpen.value=false;selected.value='';await refresh();info.value='任务已删除，已有订阅和历史保留'}catch(e){error.value=errorText(e)}}
async function saveSettings(){try{await post('/settings',settingsDraft.value);settingsOpen.value=false;info.value='设置已保存'}catch{}}
async function migrateWish(){migrationBusy.value=true;try{await post('/migration/wish');info.value='豆瓣想看已导入，新任务默认停用，请先停用旧插件再启用'}catch{}finally{migrationBusy.value=false}}
async function migrate(){migrationBusy.value=true;try{await post('/migration');info.value='旧插件数据已迁移，可在全部历史中查看'}catch{}finally{migrationBusy.value=false}}
async function rowAction(row,action){try{await post('/history/'+action,{ids:[row.id]});info.value=action==='hide'?'展示记录已隐藏，去重记录保留':'已加入下轮重试'}catch{}}
const safeLink=x=>/^https?:\/\//.test(x||'')?x:undefined
const posterUrl=x=>safeLink(x)?`/api/v1/system/img/0?imgurl=${encodeURIComponent(x)}&cache=true`:undefined
onMounted(async()=>{await refresh();timer=setInterval(()=>refresh(true),5000)})
onUnmounted(()=>clearInterval(timer))
</script>
<template>
<div class="auto-workbench">
  <div class="toolbar"><div><h2>自动订阅</h2><p class="muted">热门媒体、豆瓣榜单、演员作品、将映关注和豆瓣想看</p></div><div class="actions"><VChip :color="state.config.enabled?'success':'default'" size="small">{{state.config.enabled?'自动运行已开启':'自动运行已关闭'}}</VChip><VBtn variant="text" icon="mdi-refresh" aria-label="刷新" @click="refresh()"/><VBtn variant="tonal" @click="settingsDraft={enabled:state.config.enabled,show_sidebar:state.config.show_sidebar};settingsOpen=true">设置</VBtn><VBtn color="primary" prepend-icon="mdi-plus" @click="openEditor()">新建任务</VBtn></div></div>
  <VAlert v-if="error" type="error" variant="tonal" closable class="mb-3" @click:close="error=''">{{error}}</VAlert>
  <VAlert v-if="info" type="success" variant="tonal" closable class="mb-3" @click:close="info=''">{{info}}</VAlert>
  <div class="layout">
    <aside><VSelect v-model="sourceFilter" :items="[{title:'全部来源',value:''},...sourceOptions]" label="来源分类" hide-details density="compact" class="mb-3"/>
      <button class="all-history" :class="{active:!selected}" @click="selected='';tab='history'">全部订阅历史 <span>{{state.records.filter(r=>['subscribed','migrated','completed'].includes(r.status)&&(!sourceFilter||r.source===sourceFilter)).length}}</span></button>
      <div v-for="(t,index) in visibleTasks" :key="t.id" class="task-card" :class="{active:selected===t.id}" draggable="true" @dragstart="dragged=t.id" @dragover.prevent @drop.prevent="sortTo(dragged,t.id);dragged=''" @click="selected=t.id;tab='history'" @keydown.enter="selected=t.id" tabindex="0" role="button" :aria-label="t.name">
        <div class="task-heading"><VIcon size="18" class="muted">mdi-drag-vertical</VIcon><strong>{{t.name}}</strong><VChip size="x-small" :color="t.enabled?'success':'default'">{{t.enabled?'启用':'停用'}}</VChip></div>
        <p>{{sources[t.source]}} · {{kindOptions.find(k=>k.value===t.media_type)?.title}}</p>
        <p class="muted">{{t.source==='popular'?`订阅人次 ≥ ${t.min_popularity}`:t.source==='douban'?`豆瓣评分 ≥ ${t.min_rating}`:t.source==='actor'?t.actors.join('、'):t.source==='wish'?`同步最近 ${t.wish_days} 天的想看`:`关注 ${t.titles.length} 部作品`}}</p>
        <p class="muted">每次最多新增 {{t.max_add}} 部 · 历史 {{count(t.id)}} 部</p>
        <p class="muted small">下次运行 {{dateTime(state.next_runs[t.id])}}</p><p class="muted small">最近运行 {{dateTime(taskRuntime(t.id).finished_at)}}</p>
        <div class="card-bottom"><span class="small">{{({running:'正在扫描',queued:'已排队',failed:'等待重试',done:'最近运行完成'})[taskRuntime(t.id).status]||'等待运行'}}</span><div><VBtn size="x-small" variant="text" icon="mdi-arrow-up" aria-label="上移任务" :disabled="tasks[0]?.id===t.id||saving" @click.stop="move(t.id,-1)"/><VBtn size="x-small" variant="text" icon="mdi-arrow-down" aria-label="下移任务" :disabled="tasks.at(-1)?.id===t.id||saving" @click.stop="move(t.id,1)"/><VBtn size="x-small" variant="text" icon="mdi-pencil" aria-label="编辑任务" @click.stop="openEditor(t)"/></div></div>
      </div>
    </aside>
    <main>
      <div class="detail-heading"><div><h3>{{task?.name||'全部订阅历史'}}</h3><p class="muted">{{task?`${sources[task.source]}，独立规则和执行周期`:'可按来源、媒体类型和处理状态筛选'}}</p></div><div v-if="task" class="actions"><VBtn variant="tonal" :disabled="busy||saving" @click="run(true)">预览</VBtn><VBtn color="primary" :disabled="busy||saving||!task.enabled||!state.config.enabled" @click="run(false)">立即运行</VBtn><VBtn icon="mdi-pencil" variant="text" aria-label="编辑当前任务" :disabled="busy" @click="openEditor(task)"/><VBtn icon="mdi-delete-outline" variant="text" aria-label="删除任务" :disabled="busy" @click="deleteOpen=true"/></div></div>
      <VAlert v-if="task?.migration_note" type="warning" variant="tonal" class="my-2">{{task.migration_note}}</VAlert>
      <VAlert v-if="runtime.error" type="warning" variant="tonal" class="my-2">{{runtime.error}}</VAlert>
      <VProgressLinear v-if="busy" indeterminate color="primary" class="my-3"/>
      <VTabs v-model="tab" color="primary"><VTab value="history">订阅历史</VTab><VTab value="completed">已完成</VTab><VTab value="pending">待处理与跳过</VTab><VTab v-if="task" value="preview">预览结果</VTab><VTab value="runs">运行记录</VTab></VTabs>
      <div v-if="tab!=='runs'" class="filters"><VTextField v-model="search" label="搜索片名" prepend-inner-icon="mdi-magnify" hide-details density="compact"/><VSelect v-model="kindFilter" :items="kindOptions.filter(x=>x.value!=='all')" label="媒体类型" clearable hide-details density="compact"/><VSelect v-if="tab==='pending'" v-model="statusFilter" :items="Object.entries(statuses).map(([value,title])=>({value,title}))" label="处理状态" clearable hide-details density="compact"/></div>
      <p v-if="tab==='preview'" class="muted my-3">预览只检查条件和已有订阅，不会发起下载。执行时会重新检查。</p>
      <div v-if="tab==='runs'" class="run-list"><div v-for="(r,i) in runs" :key="i" class="run-row"><strong>{{r.task_name}}</strong><VChip size="small">{{r.preview?'预览':'订阅扫描'}}</VChip><span>{{dateTime(r.started_at)}}</span><span>{{r.error||`扫描 ${r.scanned||0} 部，新增 ${r.added||0} 部`}}</span><span>{{({done:'完成',failed:'失败',stopped:'已停止'})[r.status]||r.status}}</span></div><p v-if="!runs.length" class="empty">暂无运行记录</p></div>
      <div v-else><div class="media-grid"><article v-for="r in paged" :key="r.id" class="media-card">
        <div class="poster-wrap"><a class="poster-link" :href="safeLink(r.detail_link)" target="_blank" rel="noopener noreferrer"><img v-if="posterUrl(r.poster)&&!failedPosters.has(r.poster)" class="auto-poster-image" :src="posterUrl(r.poster)" :alt="r.title||'影视海报'" loading="lazy" @error="failedPosters.add(r.poster)"/><div v-else class="poster-placeholder"><VIcon size="36">mdi-movie-outline</VIcon><span>暂无海报</span></div></a><span class="poster-status" :class="{positive:['subscribed','migrated','completed','eligible'].includes(r.status)}">{{statuses[r.status]||r.status}}</span><span v-if="r.douban_rating||r.tmdb_rating" class="poster-rating">{{r.douban_rating?'豆瓣':'TMDB'}} {{r.douban_rating||r.tmdb_rating}}</span></div>
        <div class="media-body"><strong :title="r.title">{{r.title||'待识别作品'}}</strong><div class="media-meta"><span>{{r.year||'年份待确认'}}{{r.season?` · 第 ${r.season} 季`:''}}</span><span v-if="r.popularity">{{r.popularity}} 人订阅</span></div><p v-if="!['subscribed','migrated','completed'].includes(r.status)" class="media-reason" :title="r.reason">{{r.reason}}</p><div class="media-footer"><span class="media-origin" :title="`${r.task_name} · ${r.legacy_time||dateTime(r.time)}`">{{r.task_name==='迁移历史'?sources[r.source]:(r.task_name||sources[r.source])}}</span><div v-if="tab!=='preview'" class="media-actions"><VBtn v-if="['retry','waiting','filtered','limited'].includes(r.status)" size="x-small" variant="text" icon="mdi-refresh" aria-label="下轮重试" @click="rowAction(r,'retry')"/><VBtn size="x-small" variant="text" icon="mdi-eye-off-outline" aria-label="隐藏记录" @click="rowAction(r,'hide')"/></div></div></div>
      </article></div><p v-if="!displayed.length" class="empty">{{tab==='preview'?'点击预览，查看当前规则会选中哪些作品':'暂无记录'}}</p><VPagination v-if="displayed.length>24" v-model="page" :length="Math.ceil(displayed.length/24)" :total-visible="5"/></div>
    </main>
  </div>
  <VDialog v-model="editor" max-width="820" scrollable><VCard class="task-editor"><VCardTitle>{{editing.id?'编辑任务':'新建任务'}}</VCardTitle><VCardText class="task-editor-body"><VAlert v-if="error" type="error" variant="tonal" class="mb-3">{{error}}</VAlert><VTextField v-model="editing.name" label="任务名称"/><div class="form-grid"><VSelect v-model="editing.source" :items="sourceOptions" label="来源" :disabled="!!editing.id"/><VSelect v-model="editing.media_type" :items="kindOptions" label="媒体类型"/><VTextField v-model="editing.cron" label="执行周期" hint="Cron 表达式，例如 0 9 * * * 表示每天 9 点" persistent-hint/><VSwitch v-model="editing.enabled" label="启用任务" color="primary"/></div>
    <template v-if="editing.source==='popular'"><VTextField v-model.number="editing.min_popularity" type="number" label="最低订阅人次" hint="MoviePilot 用户订阅统计，与评分不同，需要开启系统订阅数据共享" persistent-hint/></template>
    <template v-if="editing.source==='douban'"><VSelect v-model="editing.ranks" :items="Object.entries(state.ranks).map(([value,title])=>({value,title}))" label="豆瓣榜单" multiple chips/><VTextarea v-model="textUrls" label="自定义豆瓣 RSS 地址" rows="2" hint="每行一个地址，与上方榜单合并扫描" persistent-hint/><VAlert type="info" variant="tonal" class="my-3">使用豆瓣评分筛选，TMDB 用于媒体识别。豆瓣评分获取失败时等待重试。</VAlert></template>
    <template v-if="editing.source==='wish'"><div class="form-grid"><VTextField v-model="editing.douban_user" label="豆瓣账号 ID" hint="填写个人主页 people 后面的账号 ID，不是昵称" persistent-hint/><VTextField v-model.number="editing.wish_days" type="number" label="回看最近多少天"/></div><VAlert type="info" variant="tonal" class="my-3">只同步账号动态里的想看，不导入看过或在看。首次同步受 RSS 返回范围限制，默认建议不设评分和年份门槛。</VAlert></template>
    <VTextarea v-if="editing.source==='actor'" v-model="textActors" label="演员姓名或 TMDB 人物 ID" rows="2" hint="每行一位，姓名有歧义时请使用人物 ID" persistent-hint/>
    <VTextarea v-if="editing.source==='release'" v-model="textTitles" label="关注作品" rows="4" hint="每行一部，建议包含年份，剧集可带 S02 等季数。搜索结果不唯一时等待补充信息" persistent-hint/>
    <div class="form-grid mt-4"><VTextField v-model.number="editing.min_year" type="number" label="最低年份" hint="0 表示不限"/><VTextField v-model.number="editing.min_rating" type="number" min="0" max="10" step="0.1" :label="['douban','wish'].includes(editing.source)?'最低豆瓣评分':'最低 TMDB 评分'" hint="0 表示不按评分筛选"/><VTextField v-model.number="editing.min_votes" type="number" label="最低评分人数" hint="0 表示不限"/><VSelect v-model="editing.season_mode" :items="[{title:'明确季度优先，否则第 1 季',value:'first'},{title:'未指定季度时检查全部正片季',value:'all'}]" label="剧集季度"/><VTextField v-model.number="editing.scan_limit" type="number" label="每次扫描作品数"/><VTextField v-model.number="editing.max_add" type="number" label="每次最多新增订阅" hint="重复、失败和跳过不占新增额度" persistent-hint/><VSelect v-model="editing.release_mode" :items="[{title:'识别后订阅',value:'recognized'},{title:'临近上映才订阅',value:'near_release'}]" label="订阅时机"/><VTextField v-if="editing.release_mode==='near_release'" v-model.number="editing.release_days" type="number" label="提前多少天关注上映" hint="已上映作品也会检查"/></div><VTextField v-model="editing.save_path" label="下载保存目录" hint="留空使用 MoviePilot 默认目录" persistent-hint/>
    <p class="muted mt-3">修改后保持原卡片位置和历史，新的条件从下一轮扫描生效。</p>
  </VCardText><VCardActions><VSpacer/><VBtn @click="editor=false">取消</VBtn><VBtn color="primary" :loading="saving" :disabled="!editing.name.trim()" @click="save">保存</VBtn></VCardActions></VCard></VDialog>
  <VDialog v-model="settingsOpen" max-width="550"><VCard title="自动订阅设置"><VCardText><VSwitch v-model="settingsDraft.enabled" label="启用自动运行" color="primary"/><VSwitch v-model="settingsDraft.show_sidebar" label="在订阅分组显示侧栏入口" color="primary"/><p class="muted">全局关闭后可以预览，任务不会创建新订阅，已有订阅继续由 MoviePilot 管理。</p><VDivider class="my-4"/><h4>旧插件数据迁移</h4><p class="muted my-2">导入热门媒体、豆瓣榜单、演员作品、将映关注和豆瓣想看的配置与历史，原始数据保留备份。重复迁移不会重复导入。</p><VBtn variant="tonal" :disabled="state.config.enabled||!!state.migration" :loading="migrationBusy" @click="migrate">{{state.migration?'迁移已完成':'迁移旧插件数据'}}</VBtn><VBtn variant="text" class="mt-2" :disabled="!!state.wish_migration" :loading="migrationBusy" @click="migrateWish">{{state.wish_migration?'豆瓣想看已迁移':'导入豆瓣想看'}}</VBtn><div v-if="state.migration" class="mt-3 small"><p v-for="(v,k) in state.migration" :key="k">{{k}}：历史 {{v.history}} 条，已处理 {{v.processed}} 条</p></div></VCardText><VCardActions><VSpacer/><VBtn @click="settingsOpen=false">取消</VBtn><VBtn color="primary" :loading="saving" @click="saveSettings">保存</VBtn></VCardActions></VCard></VDialog>
  <VDialog v-model="deleteOpen" max-width="420"><VCard title="删除此任务？"><VCardText>已有订阅和历史会保留，该任务不再自动运行。</VCardText><VCardActions><VSpacer/><VBtn @click="deleteOpen=false">取消</VBtn><VBtn color="error" @click="remove">删除任务</VBtn></VCardActions></VCard></VDialog>
</div>
</template>
<style scoped>
